WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_judgement_definition_single_multi_elements'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多要件匹配', 'kp-xingce-judgement-definition-single-multi-elements', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "定义判断：多要件匹配"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "拆解要件，缺一不可。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读长定义] --> B[用笔拆分出 主体、客体、条件、方式、目的 等 3-4 个并列要件]\nB --> C[在选项中逐一核对这几个要件]\nC --> D[只要有一个要件不符合, 该选项立即判死刑, 看下一个]"}}]}$$ AS jsonb), NULL, '多要件匹配的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "多要件匹配"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_definition_single_multi_elements", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
